def compute(vars):
    stock_options_millions = vars["v1"]
    average_exercise_price = vars["v2"]
    total_value_millions = stock_options_millions * average_exercise_price

    return {
        "value": total_value_millions,
        "trace": {
            "stock_options_millions": stock_options_millions,
            "average_exercise_price_usd_per_share": average_exercise_price,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "dollars",
            },
        },
    }
